import{_ as t,c as s,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易輯聞","description":"周易輯聞 - 周易輯聞","frontmatter":{"title":"周易輯聞","description":"周易輯聞 - 周易輯聞"},"headers":[],"relativePath":"classics/jiwen/001.md","filePath":"classics/jiwen/001.md"}'),r={name:"classics/jiwen/001.md"};function i(c,a,o,p,d,m){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易輯聞",tabindex:"-1"},[l("周易輯聞 "),e("a",{class:"header-anchor",href:"#周易輯聞","aria-label":"Permalink to “周易輯聞”"},"​")],-1),e("p",null,"廣大無不備，夫惟易道然。輯聞傳汴水，述學衍先天。觀彼多合聖，切子斯體乾。影鈔猶識宋，遠矣緬韋編。欽定四庫全書經部一週易輯聞易類提要：",-1),e("p",null,"臣 等謹案：周易輯聞六卷、附易雅一卷、筮宗一卷，宋趙汝梅撰。汝梅，商王元份之七世孫，資政殿大學士善湘之子，理宗時官至戶部侍郎。考宋史趙善湘傅載其說易之書，有約說八卷、或問四卷、指要四卷、續問八卷、補過六卷。蓋研究是經，用功最久，故汝梅承其家",-1),e("p",null,"學，以作是編。其說據漢書儒林傳稱費直惟以彖、象、繋辭十篇文言解說上下經，疑說卦、序卦、雜卦皆為漢儒竄入。又以繋辭多稱「子曰」，定為門人所記，非夫子之書，因置此諸傅，惟注經文。其以彖傅散附彖辭，小象散附爻辭，仍用王弼之本。其以大象移於卦畫之後，彖辭之前，以文言散附乾坤彖傅及小象後，則又汝梅之新意。割裂顛倒，殊屬師心。又王弼本雖移傅附經，尚有「彖曰」、「象曰」、「文言曰」字，以存識別，汝梅並此而去之，致使經傳混淆，範然莫辨，尤為治絲而棼。其每卦之首，皆以卦變立論，亦未免偏主一隅。然其說推闡詳明，於比應乘承之理，盈虛消長之機，皆有所發揮，不同穿鑿。於宋人易說之中，猶為明白篤實。易雅一卷，總釋名義，略如爾雅之釋詩，故名曰「雅」。其目：曰通釋，曰書釋，曰學釋，曰情釋，曰位釋，曰象釋，曰辭釋，曰變釋，曰佔釋，曰卦變釋，曰爻變釋，曰得失釋，曰八卦釋，曰六爻釋，曰陰陽釋，曰太極名義釋，曰象數體用釋，曰圖書釋，凡十八篇。其論圖書曰：「易有衍數，有積數。自五衍而為五十者，衍數也；自一、二、三、四、五積而為五十五者，積數也。圖書二數皆積數之儔，不可以與於揲蓍也。故舍圖書之名而論二數，則自有妙理；強二數以圖、書之名，則於經無據。」可謂喜於解紛矣。筮宗一卷，朱彝尊經義考作三卷，蓋是書原本題明本第一，述筮第二先傅考第三，彝尊以一篇為一卷也。其推明大衍之數，頗為明白，於諸家舊說，一一條辨，亦具有考證雲。乾隆四十四年九月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。周易輯聞原序：",-1),e("p",null,"易道函三極而神萬化，易書立三極而萬化神。道主於有，書主於用也。體易君子處而用身，出而用世，皆於此焉出以用為動，則靜者其體也。動之變無窮，近而顯者，百姓與能；遠而微者，賢智未易知。夫道妙於無形，而著於有象，確乎不易，而變動不居。以虛而言，則至於無畔；以固而言，則或有所不通。聖人於是立象倚數，探賾索隱，載之於書，莫非日用常行之實。使人因有象而悟無形之妙，即變易以求不易之方，玩而體之，服而行之，言有據而動有則，措諸事業，自誠意正心以至於齊家治國平天下，隨用輒效。此體用兼該之學，伏羲畫卦之旨，文、周憂世之情，夫子傳易之志也。汝梅齒耄學荒，何敢言易？獨念先君子自始至夫，於易凡六稿，日進日益，末稿題曰「補過」，汝梅得於口授者居多。外除以來逾二十載，因輯所聞於篇，庶不忘先君子之教，且以觀吾過雲。汴水趙汝梅序。",-1)])])}const f=t(r,[["render",i]]);export{_ as __pageData,f as default};
